Q = [
    make(1, "要判斷某種生物構造是否有助於適應環境，哪條證據鏈最完整？", {"A": "特定環境壓力→可辨認的構造差異→可測量的功能結果→生存或繁殖表現", "B": "看到外形特別→推測生物有意設計→直接宣布一定適應", "C": "產品外觀相似→不需測試就宣稱具相同功能", "D": "只知道生物名稱→即可判斷所有環境中的優勢"}, "適應判斷需要把環境問題、構造特徵、功能表現與結果連起來；只看外觀或把生物當成有意設計者，都缺乏可檢驗證據。", "先找環境壓力，再找構造與功能的可測量連結，最後檢查是否有結果資料。", ["標出題目要求的適應判斷，而非單純外形描述。", "列出特定環境可能造成的壓力。", "找出與壓力對應的構造差異。", "安排功能測量與生存／繁殖結果作為後續證據。", "所以選 A。"], "medium"),
    make(2, "蓮葉表面常能讓水滴較容易滾落，若要解釋此現象，哪項最合理？", {"A": "表面微小突起與低表面能可減少水滴接觸，水滴較不易攤開並可能帶走灰塵", "B": "蓮葉會把水滴吸入葉脈，所以表面一定完全乾燥", "C": "所有葉片都有相同微結構，因此排水效果必然相同", "D": "水滴能滾落是因為葉片會主動把水推走，不需表面結構"}, "微結構與材料表面性質會影響水滴接觸角與附著，水滴滾動時可能帶走部分灰塵；不能把現象歸因於葉片有意推水。", "從表面結構與材料性質推論水滴行為，並避免把觀察誇大成所有葉片都相同。", ["先找出水滴行為是攤開、附著或滾落。", "連結微小突起與低表面能對接觸面積的影響。", "推論接觸角與滾動能力可能改變。", "保留不同葉片、污染與傾角等條件限制。", "所以選 A。"], "medium"),
    make(3, "比較平滑表面與仿蓮葉表面的排水效果時，哪個實驗設計最公平？", {"A": "固定水滴體積、表面傾角與溫度，只改變表面是否具有微結構，並量測滾動時間與殘留面積", "B": "仿蓮葉表面用大水滴，平滑表面用小水滴，再比較誰先滾落", "C": "一面放在室內，一面放在雨中，只記錄研究者感覺", "D": "只拍一滴水的照片，不記錄傾角、時間或表面狀態"}, "公平測試要固定可能影響結果的條件，只改變表面微結構，並用相同指標量測；否則無法把差異歸因於仿生表面。", "實驗設計題採『固定—只改一項—量測—重複』檢查。", ["先指定自變因是表面微結構。", "固定水量、傾角、溫度與量測方式。", "選擇滾動時間、殘留面積等可比較指標。", "避免不同水滴大小、環境與主觀感覺造成混淆。", "所以選 A。"], "easy"),
    make(4, "把蓮葉自潔原理轉成雨水感測器外殼時，哪項設計最符合仿生而非只模仿外形？", {"A": "測量蓮葉表面結構與水滴行為，再以相近微結構和表面性質製作外殼並驗證感測穩定度", "B": "把外殼漆成綠色、畫上葉脈，就能宣稱具有蓮葉自潔功能", "C": "只增加外殼重量，因為蓮葉漂浮所以產品也應更重", "D": "複製葉片大小即可保證水滴會以相同速度滾落"}, "仿生要轉譯造成效果的機制與尺度，再用產品指標驗證；顏色、葉脈圖案或大小相似不等於保留蓮葉的表面功能。", "先找自然構造真正造成的功能，再將它轉成工程材料與可測量規格。", ["分辨蓮葉的顏色與自潔機制不是同一件事。", "找出微結構與表面性質對水滴行為的作用。", "把作用轉成外殼材料與製程需求。", "用排水時間、殘留面積與感測穩定度測試。", "所以選 A。"], "hard"),
    make(5, "壁虎腳部能在垂直表面附著，若設計可重複使用的攀爬貼片，最需要先研究哪項？", {"A": "腳部微細結構與接觸面間的作用，並測量不同表面粗糙度下的附著力與脫離次數", "B": "只研究壁虎的體色，因為顏色越接近牆面附著力越大", "C": "只增加貼片厚度，不必比較表面材料或接觸面", "D": "看到壁虎能爬牆，就可保證貼片能承受所有人的重量"}, "仿生貼片要保留附著的微細結構與界面作用，並在不同表面條件下量測附著力、耐久度與失效情況，不能由單一生物觀察直接保證所有負載。", "仿生應用要把生物功能拆成機制、材料、尺度與負載測試。", ["先確認要模仿的是附著功能而非體色。", "找出腳部微細結構與接觸界面的研究對象。", "設計粗糙度、負載與重複使用次數的測試。", "記錄附著力與失效條件，不過度外推到所有重量。", "所以選 A。"], "hard"),
    make(6, "蝙蝠利用回聲定位在黑暗中辨認障礙物，仿生設計要建立的核心對應為何？", {"A": "發出訊號、接收反射回波，再由回波時間或特徵估算物體距離與形狀", "B": "模仿蝙蝠的翅膀顏色，就能在黑暗中看見物體", "C": "只播放固定聲音，不需接收回波也能測距", "D": "讓儀器發光即可完全取代回聲訊息"}, "回聲定位依靠訊號發出、回波接收與特徵分析；仿生儀器要保留資訊處理機制，而不是只複製外觀。", "把生物行為拆成輸入、反射訊號、接收與推論四個模組。", ["辨認蝙蝠使用的是聲音訊號而非顏色。", "標出發出訊號與遇到物體反射。", "量測回波到達時間或頻率等特徵。", "將資料轉換成距離或形狀估計，排除只播放或只發光。", "所以選 A。"], "medium"),
    make(7, "若同一種表面在乾燥環境排水很好，塗上油污後效果大幅下降，最合理的結論是？", {"A": "仿生功能受材料表面狀態影響，不能只用乾燥清潔條件的結果宣稱所有情境都有效", "B": "實驗一定錯誤，因為仿生構造不可能受污染影響", "C": "油污證明微結構永遠比材料性質重要", "D": "只要把表面做得更像葉子，任何污染都不會改變結果"}, "水滴行為同時受微結構與表面材料性質影響，油污可能改變表面能與接觸狀態；因此要把環境條件寫入產品限制。", "資料判讀題先比較條件差異，再把差異轉成機制與使用限制。", ["列出乾燥清潔與油污表面是兩個不同條件。", "確認污染可能改變表面材料性質。", "把排水下降連到接觸狀態改變。", "將結論限制在已測條件，不宣稱所有環境均有效。", "所以選 A。"], "medium"),
    make(8, "有人說：『長頸鹿有長脖子是因為牠想吃高處葉子，所以身體主動把脖子拉長。』哪項修正最科學？", {"A": "應比較環境資源、族群變異、遺傳與繁殖結果，不能把適應描述成個體為達目的而主動設計", "B": "正確，所有生物構造都是依照當下願望立即改變", "C": "錯誤，生物構造與環境永遠沒有關係", "D": "只要看到長脖子，就能證明每隻長頸鹿都吃高處葉子"}, "適應是族群在世代中受到變異與選擇等作用後形成的構造—功能關係，不能把個體的目的想像當成演化證據；仍需資料支持構造與環境的關聯。", "概念題先修正目的論，再補上族群、世代與證據三個尺度。", ["指出原句把個體願望當成構造成因。", "改用族群中變異與環境壓力描述。", "加入繁殖成功與世代累積的證據需求。", "不把單一長脖子個體外推成所有功能結論。", "所以選 A。"], "hard"),
    make(9, "若仿生雨水感測器的目標是讓水滴快速離開感測面，哪組規格最能直接檢驗設計成效？", {"A": "固定水量與傾角，量測水滴滾動時間、殘留面積與感測讀值恢復時間", "B": "只記錄外殼顏色與是否像葉片，不記錄水滴行為", "C": "只問使用者覺得漂亮不漂亮，不做重複測量", "D": "把感測器放在任意角度，每次使用不同水量再比較結果"}, "目標是快速排水並恢復感測，應量測滾動時間、殘留面積與讀值恢復，且固定水量與傾角才能比較。", "規格題先把功能目標改寫成可量化指標，再補上公平測試條件。", ["把『快速離開』轉成時間與殘留面積。", "把『感測器恢復』轉成讀值恢復時間。", "固定水量、傾角與測量程序。", "排除顏色、喜好與每次不同條件造成的不可比資料。", "所以選 A。"], "medium"),
    make(10, "要判斷仿生設計是否真的保留自然構造的作用原理，哪項資料最有說服力？", {"A": "仿生表面與平滑對照在相同條件下的多次測量，並說明微結構、材料與失效條件", "B": "產品名稱含有『蓮葉』兩字", "C": "一張產品外觀與蓮葉相似的照片", "D": "設計者表示靈感來自自然，所以不需對照實驗"}, "外觀或名稱只能說明靈感來源；相同條件的對照、多次測量、機制資料與失效條件，才可支持仿生原理是否被保留。", "證據題採『對照—重複—機制—限制』四層回查。", ["先確認要比較的是功能而非外觀。", "設置平滑表面作對照並固定環境條件。", "重複量測排水或附著等功能指標。", "補上微結構、材料與失效條件，避免過度宣稱。", "所以選 A。"], "hard"),
]

for index, target in {2: "B", 4: "C", 6: "D", 8: "B", 10: "C"}.items():
    q = Q[index - 1]
    option_map = {o["id"]: o["text"] for o in q["options"]}
    option_map["A"], option_map[target] = option_map[target], option_map["A"]
    q["options"] = [{"id": k, "text": option_map[k]} for k in ("A", "B", "C", "D")]
    q["answer"]["value"] = target
    q["answer"]["explanation"] = q["answer"]["explanation"].replace("選 A。", f"選 {target}。")
    q["solutionSteps"] = [s.replace("所以選 A。", f"所以選 {target}。") for s in q["solutionSteps"]]

for q in Q:
    (OUT / f"{q['id']}.json").write_text(json.dumps(q, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
print(f"rewrote {len(Q)} questions")
